import numpy as np
import mujoco
from scipy.spatial.transform import Rotation

class Controller:
    def __init__(self,s):
        self.s=s; self.m=s.model
        self.ikd=mujoco.MjData(self.m)
        self.jids=np.array([self.m.joint(f'robot0_joint{i}').id for i in range(1,8)])
        self.qids=self.m.jnt_qposadr[self.jids]; self.dofs=self.m.jnt_dofadr[self.jids]
        self.sid=self.m.site('gripper0_right_grip_site').id
        self.door=self.m.joint(s.env.fxtr._joint_names['door']).id
        self.grip=-1
    def pose(self):
        return self.s.data.site_xpos[self.sid].copy(),self.s.data.site_xmat[self.sid].reshape(3,3).copy()
    def ik(self,p,R,q=None):
        d=self.ikd;m=self.m
        d.qpos[:]=self.s.data.qpos
        if q is not None:d.qpos[self.qids]=q
        jp=np.zeros((3,m.nv));jr=np.zeros((3,m.nv))
        for i in range(150):
            mujoco.mj_kinematics(m,d);mujoco.mj_comPos(m,d)
            e=np.r_[p-d.site_xpos[self.sid],Rotation.from_matrix(R@d.site_xmat[self.sid].reshape(3,3).T).as_rotvec()]
            if np.linalg.norm(e)<1e-5:break
            mujoco.mj_jacSite(m,d,jp,jr,self.sid)
            J=np.vstack([jp[:,self.dofs],jr[:,self.dofs]])
            dq=J.T@np.linalg.solve(J@J.T+np.eye(6)*1e-5,e)
            dq*=min(1,.12/(max(abs(dq))+1e-10))
            d.qpos[self.qids]=np.clip(d.qpos[self.qids]+dq,m.jnt_range[self.jids,0]+.005,m.jnt_range[self.jids,1]-.005)
        return d.qpos[self.qids].copy(),np.linalg.norm(e)
    def stepq(self,q,grip=None,base=None):
        a=np.zeros(13);a[:7]=q;a[7]=self.grip if grip is None else grip;a[-1]=-1
        if base is not None:a[8:11]=base
        return self.s.step(a)
    def move(self,p,R=None,n=80,grip=None):
        p0,R0=self.pose();R=R0 if R is None else R
        dr=Rotation.from_matrix(R@R0.T).as_rotvec()
        q=self.s.data.qpos[self.qids].copy()
        for i in range(n):
            t=(i+1)/n;t=t*t*(3-2*t)
            q,err=self.ik(p0+(p-p0)*t,Rotation.from_rotvec(dr*t).as_matrix()@R0,q)
            self.stepq(q,grip)
        print('move',len(self.s.actions),'pos',self.pose()[0],'err',err,'door',self.angle(),'success',self.s.check()['success'],flush=True)
    def hold(self,n=20,grip=None):
        q=self.s.targets[:7].copy()
        for _ in range(n):self.stepq(q,grip)
        if grip is not None:self.grip=grip
        print('hold',len(self.s.actions),'pos',self.pose()[0],'door',self.angle(),flush=True)
    def angle(self):return self.s.data.qpos[self.m.jnt_qposadr[self.door]]
    def contacts(self):
        out=[]
        for c in self.s.data.contact:
            n1=self.m.geom(c.geom1).name;n2=self.m.geom(c.geom2).name
            if ('gripper' in n1 or 'gripper' in n2) and ('dishwasher' in n1 or 'dishwasher' in n2):out.append((n1,n2,c.dist))
        return out
